// Expansion pack: Pyramids of the World (and beyond).
// Olmec -> Maya -> Aztec -> Cahokia -> Deseret -> Mars -> (time machine) -> Egypt.

const steps = (bases, h, batter) => bases.map((a, i) => ({ z0: i * h, z1: (i + 1) * h, a0: a, a1: a - batter }));

const BASE_DECREES = {
  feast: { name: 'Great Feast', desc: 'Food, drink, music. Big morale boost. Ends a strike.', logText: 'A great feast! Drums, dancing and full bellies.' },
  levy: { name: 'Labor Draft', desc: 'Call laborers from the surrounding villages for the rest of the season. Costs goodwill; during farming seasons it cuts the next tribute.', logText: 'Messengers run out to the villages: the ruler needs hands.' },
  rations: { name: 'Extra Rations', desc: 'Larger rations for 90 days. Morale up, food down.', logText: 'Extra rations for everyone.' },
  tax: { name: 'Emergency Tribute', desc: 'Squeeze the villages for food. Morale drops for months.' },
  allgods: { name: 'Offerings to All', desc: '+10 favor with every patron.', logText: 'Offerings are laid at every shrine.' },
};

const MESO_BUILDINGS = {
  village: { name: 'Houses', desc: 'Housing for workers and their families.' },
  granary: { name: 'Storehouses', desc: 'Food storage. From level 3 it is protected from floods.' },
  bakery: { name: 'Kitchens', desc: 'Room for more cooks.' },
  quarry: { name: 'Quarry', desc: 'Room for more quarry workers.' },
  harbor: { name: 'Landing', desc: 'Room for more canoe crews.' },
  temple: { name: 'Temple precinct', desc: 'Room for more priests, who also study faster.' },
};

function civ(c) {
  return {
    rates: { quarry: 1, haul: 1, mason: 1, boat: 1, tools: 1 },
    decrees: BASE_DECREES,
    buildings: MESO_BUILDINGS,
    strikeLine: '<b>Strike!</b> The work crews sit down: "No food, no work."',
    chaosLine: 'Order has collapsed. People drift away to other cities, and the forest begins to take the plaza back.',
    rampagePaid: 'The crisis passes.',
    rampageLost: 'Disaster strikes the camp.',
    ...c,
  };
}

